//! Symmetry: deck-group generators + fundamental domain; cut-and-keep-chamber; unfold.
//!
//! The model's topology **is** the fundamental domain `F`. The deck group `G` is generated by the
//! deck boundaries (each [`crate::boundary::BoundaryRow`] with a `Deck` kind is a generator, so the
//! transform is declared once, on the boundary). The full model is `⋃ g·F`; [`Model::unfold`]
//! derives it as a list of [`Placed`] copies plus gluing data, without touching the tables, so
//! it is reversible by construction: every unfolded entity names its base entity.

use crate::action::{Axis, GroupAction, Placed, Plane, compose, inverse};
use crate::boundary::{BoundaryKind, Deck};
use crate::error::{ModelError, Result};
use crate::model::{Lineage, Model};
use crate::topology::{Tolerance, TopologyView};
use sm_core::{EntityId, EntityKind, Vector3};
use std::collections::{BTreeMap, BTreeSet};

/// How the symmetry came to be.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
pub enum SymmetryOrigin {
    /// Stated by the user or an importer (existing faces tagged as deck boundaries).
    Declared,
    /// Found by [`crate::detect::detect_symmetry`] and accepted.
    Detected,
    /// Produced by [`Model::cut_and_keep_chamber`].
    Cut,
}

/// The symmetry record (at most one per model).
#[derive(Clone, Debug, PartialEq)]
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
pub struct Symmetry {
    /// Generators: `Boundary` ids whose kind is `Deck`, in declaration order.
    pub generators: Vec<EntityId>,
    /// The fundamental domain: its `TopoVolume`s, sorted ascending.
    pub domain: Vec<EntityId>,
    /// Provenance.
    pub origin: SymmetryOrigin,
}

/// Which side of a mirror plane a cut keeps.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
pub enum Keep {
    /// The side the plane normal points to.
    Positive,
    /// The opposite side.
    Negative,
}

/// The geometric cut that produces a chamber (the request handed to the topology kernel).
#[derive(Clone, Copy, Debug, PartialEq)]
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
pub enum ChamberCut {
    /// Cut by a plane and keep one side; the new faces are mirror deck boundaries.
    Mirror {
        /// The plane.
        plane: Plane,
        /// Which side to keep.
        keep: Keep,
    },
    /// Keep the slab between `plane_a` and `plane_a` shifted by `shift`; caps are translation pairs A -> B = A + shift.
    Periodic {
        /// The A-side plane.
        plane_a: Plane,
        /// Shift from A to B.
        shift: Vector3,
    },
    /// Keep the sector from the half-plane `(axis, start)` through `2π/order`; caps are rotation pairs.
    Wedge {
        /// Rotation axis.
        axis: Axis,
        /// Sector angle is `2π/order`.
        order: u32,
        /// Direction (perpendicular to the axis) of the A half-plane.
        start: Vector3,
    },
}

impl ChamberCut {
    /// The deck record the cut's cap faces get.
    pub fn deck(&self) -> Deck {
        match *self {
            ChamberCut::Mirror { plane, .. } => Deck::Mirror { plane },
            ChamberCut::Periodic { shift, .. } => Deck::Translation { shift },
            ChamberCut::Wedge { axis, order, .. } => Deck::Rotation { axis, order },
        }
    }
}

/// A cut-and-keep request.
#[derive(Clone, Debug, PartialEq)]
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
pub struct ChamberSpec {
    /// Geometry of the cut.
    pub cut: ChamberCut,
    /// Name for the new deck boundary record.
    pub name: String,
    /// Boundary color for the new cap faces, if any.
    pub cap_color: Option<EntityId>,
}

/// A new cap face made by a cut.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
pub struct CapFace {
    /// The new face (side A).
    pub face: EntityId,
    /// Its B-side partner for paired cuts; `None` for mirrors.
    pub mate: Option<EntityId>,
}

/// What the topology kernel reports after executing a [`ChamberSpec`]. This is the **contract
/// the topology op must satisfy**: lineage for every old volume/face that changed or was removed
/// (unlisted ids are unchanged), plus the cap faces.
#[derive(Clone, Debug, PartialEq)]
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
pub struct CutOutcome {
    /// Old -> new volumes and faces.
    pub lineage: Vec<Lineage>,
    /// New cap faces.
    pub caps: Vec<CapFace>,
}

/// A base entity seen in one copy of an unfolded model.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
pub struct CopyRef {
    /// Index into [`UnfoldedModel::copies`].
    pub copy: u32,
    /// The entity of the fundamental domain.
    pub base: EntityId,
}

/// A volume of the unfolded model.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
pub struct UnfoldedVolume {
    /// Which copy of which base volume.
    pub at: CopyRef,
    /// Its color (same as the base volume's: group actions never change colors).
    pub color: Option<EntityId>,
}

/// Two deck faces glued into one interior face of the unfolded model.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
pub struct Glue {
    /// One side.
    pub a: CopyRef,
    /// The other side (same base face for a mirror).
    pub b: CopyRef,
    /// The deck boundary record responsible.
    pub boundary: EntityId,
}

/// A deck face with no neighbour in the unfolded model (e.g. the ends of a finite translation tiling).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
pub struct ExposedFace {
    /// Where.
    pub at: CopyRef,
    /// The deck boundary record.
    pub boundary: EntityId,
}

/// Parameters of an unfold.
#[derive(Clone, Debug, PartialEq)]
pub struct UnfoldSpec {
    /// Repeat counts for translation generators (required for each of them).
    pub repeats: BTreeMap<EntityId, u32>,
    /// Element budget.
    pub max_copies: usize,
    /// Tolerance for identifying group elements.
    pub tol: Tolerance,
}

impl Default for UnfoldSpec {
    fn default() -> Self {
        Self { repeats: BTreeMap::new(), max_copies: 4096, tol: Tolerance::default() }
    }
}

/// The derived full model. Copy 0 is always the identity (the fundamental domain itself).
#[derive(Clone, Debug, PartialEq)]
pub struct UnfoldedModel {
    /// The copies; index = `CopyRef::copy`.
    pub copies: Vec<Placed>,
    /// Volumes of all copies, ascending by `(copy, base)`.
    pub volumes: Vec<UnfoldedVolume>,
    /// Interior faces made by gluing deck pairs.
    pub glued: Vec<Glue>,
    /// Deck faces left open.
    pub exposed: Vec<ExposedFace>,
}

impl UnfoldedModel {
    /// Fold back: the base entity an unfolded entity came from. Unfolding is a pure view, so this
    /// is the whole inverse.
    pub fn fold(&self, r: CopyRef) -> EntityId {
        r.base
    }

    /// The uses of base face `face` in copy `copy` by that copy's own volumes, with senses
    /// relative to the image of the base loop: flipped for improper copies, whose image loops
    /// run against the outward normal (reverse the loop to restore the left/right rule).
    pub fn own_face_sides(&self, topo: &dyn TopologyView, copy: u32, face: EntityId) -> Vec<(CopyRef, crate::topology::Sense)> {
        let improper = self.copies.get(copy as usize).is_some_and(|c| c.improper);
        topo.face_sides(face).iter().map(|s| (CopyRef { copy, base: s.volume }, s.sense.under(improper))).collect()
    }
}

impl Model {
    /// Declare a symmetry whose generators are existing deck boundaries and whose fundamental
    /// domain is `domain` (sorted for you).
    pub fn declare_symmetry(&mut self, generators: &[EntityId], domain: &[EntityId], origin: SymmetryOrigin) -> Result<()> {
        for g in generators {
            crate::color::expect_kind(*g, EntityKind::Boundary)?;
            match self.boundaries.get(g) {
                None => return Err(ModelError::Unknown(*g)),
                Some(b) if b.kind.as_deck().is_none() => return Err(ModelError::Invalid(format!("{g} is not a deck boundary"))),
                Some(_) => {}
            }
        }
        let mut domain = domain.to_vec();
        domain.sort();
        domain.dedup();
        self.symmetry = Some(Symmetry { generators: generators.to_vec(), domain, origin });
        Ok(())
    }

    /// Execute the semantic half of cut-and-keep-chamber: given what the topology kernel did
    /// ([`CutOutcome`]), re-key all tables through its lineage, create the deck boundary record
    /// for the cap faces (deck pairs / mirror faces are tagged immediately), color the caps,
    /// and register the new generator. Transactional.
    pub fn cut_and_keep_chamber(&mut self, spec: &ChamberSpec, outcome: &CutOutcome) -> Result<EntityId> {
        let deck = spec.cut.deck();
        if let ChamberCut::Wedge { axis, start, .. } = spec.cut
            && start.dot(axis.dir).abs() > 1e-9 * start.norm().max(1.0)
        {
            return Err(ModelError::Invalid("wedge start direction must be perpendicular to the axis".into()));
        }
        let mut next = self.clone();
        next.apply_lineage(&outcome.lineage)?;
        let boundary = next.add_boundary(&spec.name, BoundaryKind::Deck(deck))?;
        if deck.is_self_paired() {
            let faces: Vec<EntityId> = outcome.caps.iter().map(|c| c.face).collect();
            next.assign_faces(boundary, &faces)?;
        } else {
            let mut pairs = Vec::with_capacity(outcome.caps.len());
            for c in &outcome.caps {
                let b = c.mate.ok_or_else(|| ModelError::Invalid(format!("cap face {} needs a mate for a paired cut", c.face)))?;
                pairs.push((c.face, b));
            }
            next.assign_pairs(boundary, &pairs)?;
        }
        if let Some(col) = spec.cap_color {
            for c in &outcome.caps {
                next.color_face(c.face, col)?;
                if let Some(m) = c.mate {
                    next.color_face(m, col)?;
                }
            }
        }
        let new_volumes = outcome.lineage.iter().flat_map(|l| l.new.iter().copied()).filter(|i| i.kind() == EntityKind::TopoVolume);
        match &mut next.symmetry {
            Some(s) => s.generators.push(boundary),
            None => {
                let domain: BTreeSet<EntityId> = next.volume_color.keys().copied().chain(new_volumes).collect();
                next.symmetry = Some(Symmetry { generators: vec![boundary], domain: domain.into_iter().collect(), origin: SymmetryOrigin::Cut });
            }
        }
        *self = next;
        Ok(boundary)
    }

    /// Derive the full model `⋃ g·F`.
    ///
    /// Finite generators (mirror, rotation) are closed under composition. Translation
    /// generators need `spec.repeats` and tile as `T^i · g` (valid when translations commute
    /// with the finite part; the ends of the tiling stay exposed deck faces).
    pub fn unfold(&self, spec: &UnfoldSpec) -> Result<UnfoldedModel> {
        let sym = self.symmetry.as_ref().ok_or(ModelError::NoSymmetry)?;
        let mut point = Vec::new();
        let mut tiles = Vec::new();
        let mut gens = Vec::new();
        for b in &sym.generators {
            let deck = *self.boundaries.get(b).and_then(|r| r.kind.as_deck()).ok_or(ModelError::Unknown(*b))?;
            let t = deck.transform();
            match deck.order() {
                Some(_) => point.push(t),
                None => tiles.push((t, *spec.repeats.get(b).ok_or(ModelError::MissingRepeats(*b))?)),
            }
            gens.push((*b, t));
        }
        let action = GroupAction::closure(&point, spec.max_copies, &spec.tol)?.tiled(&tiles, spec.max_copies)?;
        let copies = action.placements();

        let mut volumes = Vec::with_capacity(copies.len() * sym.domain.len());
        for k in 0..copies.len() as u32 {
            for v in &sym.domain {
                volumes.push(UnfoldedVolume { at: CopyRef { copy: k, base: *v }, color: self.volume_color.get(v).copied() });
            }
        }

        let (mut glued, mut exposed) = (Vec::new(), Vec::new());
        for (b, s) in &gens {
            let s_inv = inverse(s)?;
            let paired = self.boundaries[b].kind.is_paired();
            let pairs = self.boundary_pairs(*b);
            for (k, e) in action.elements().iter().enumerate() {
                let k = k as u32;
                let behind = action.index_of(&compose(e, &s_inv), &spec.tol);
                let ahead = action.index_of(&compose(e, s), &spec.tol);
                for (a, mate) in &pairs {
                    match behind {
                        Some(j) if !paired => {
                            if k < j as u32 {
                                glued.push(Glue { a: CopyRef { copy: k, base: *a }, b: CopyRef { copy: j as u32, base: *a }, boundary: *b });
                            }
                        }
                        Some(j) => glued.push(Glue { a: CopyRef { copy: k, base: *a }, b: CopyRef { copy: j as u32, base: *mate }, boundary: *b }),
                        None => exposed.push(ExposedFace { at: CopyRef { copy: k, base: *a }, boundary: *b }),
                    }
                    if paired && ahead.is_none() {
                        exposed.push(ExposedFace { at: CopyRef { copy: k, base: *mate }, boundary: *b });
                    }
                }
            }
        }
        Ok(UnfoldedModel { copies, volumes, glued, exposed })
    }
}
